/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  /* D := alpha*A*B*C + beta*D */
  {
    const int TI = 32;
    const int TJ = 32;
    const int TK = 32;

    int ii, jj, kk;

#pragma omp parallel default(none) shared(A,B,C,D,tmp,alpha,beta) private(i,j,k,ii,jj,kk)
    {
      /* Phase 1: tmp = alpha * A * B (tiled i/j/k) */
#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NI; ii += TI)
        for (jj = 0; jj < _PB_NJ; jj += TJ)
          for (i = ii; i < _PB_NI && i < ii + TI; ++i)
            for (j = jj; j < _PB_NJ && j < jj + TJ; ++j)
              tmp[i][j] = SCALAR_VAL(0.0);

#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NI; ii += TI)
        for (jj = 0; jj < _PB_NJ; jj += TJ)
          for (kk = 0; kk < _PB_NK; kk += TK)
            for (i = ii; i < _PB_NI && i < ii + TI; ++i)
              for (k = kk; k < _PB_NK && k < kk + TK; ++k) {
                const DATA_TYPE a_ik = alpha * A[i][k];
#pragma omp simd
                for (j = jj; j < _PB_NJ && j < jj + TJ; ++j)
                  tmp[i][j] += a_ik * B[k][j];
              }

#pragma omp barrier

      /* Phase 2: D = beta*D + tmp*C (tiled i/j/k over D(i,j) and reduction k over NJ) */
#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NI; ii += TI)
        for (jj = 0; jj < _PB_NL; jj += TJ)
          for (i = ii; i < _PB_NI && i < ii + TI; ++i)
            for (j = jj; j < _PB_NL && j < jj + TJ; ++j)
              D[i][j] *= beta;

#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NI; ii += TI)
        for (jj = 0; jj < _PB_NL; jj += TJ)
          for (kk = 0; kk < _PB_NJ; kk += TK)
            for (i = ii; i < _PB_NI && i < ii + TI; ++i)
              for (k = kk; k < _PB_NJ && k < kk + TK; ++k) {
                const DATA_TYPE t_ik = tmp[i][k];
#pragma omp simd
                for (j = jj; j < _PB_NL && j < jj + TJ; ++j)
                  D[i][j] += t_ik * C[k][j];
              }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
