    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#pragma scop
  {
    /* Cache blocking parameters (tunable). */
    const int TI = 32;
    const int TJ = 32;
    const int TK = 32;

    int ii, jj, kk;

    /* One persistent team to reduce fork/join overhead.
       E and F are computed in separate omp for loops; barrier between loops is implicit. */
#pragma omp parallel default(none) shared(A,B,C,D,E,F,G) private(i,j,k,ii,jj,kk)
    {
      /* E := A*B (tiled) */
#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NI; ii += TI)
        for (jj = 0; jj < _PB_NJ; jj += TJ)
          {
            int i_end = ii + TI; if (i_end > _PB_NI) i_end = _PB_NI;
            int j_end = jj + TJ; if (j_end > _PB_NJ) j_end = _PB_NJ;

            for (i = ii; i < i_end; ++i)
              for (j = jj; j < j_end; ++j)
                E[i][j] = SCALAR_VAL(0.0);

            for (kk = 0; kk < _PB_NK; kk += TK)
              {
                int k_end = kk + TK; if (k_end > _PB_NK) k_end = _PB_NK;

                for (i = ii; i < i_end; ++i)
                  for (k = kk; k < k_end; ++k)
                    {
                      DATA_TYPE aik = A[i][k];
#pragma omp simd
                      for (j = jj; j < j_end; ++j)
                        E[i][j] += aik * B[k][j];
                    }
              }
          }

      /* F := C*D (tiled) */
#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NJ; ii += TI)
        for (jj = 0; jj < _PB_NL; jj += TJ)
          {
            int i_end = ii + TI; if (i_end > _PB_NJ) i_end = _PB_NJ;
            int j_end = jj + TJ; if (j_end > _PB_NL) j_end = _PB_NL;

            for (i = ii; i < i_end; ++i)
              for (j = jj; j < j_end; ++j)
                F[i][j] = SCALAR_VAL(0.0);

            for (kk = 0; kk < _PB_NM; kk += TK)
              {
                int k_end = kk + TK; if (k_end > _PB_NM) k_end = _PB_NM;

                for (i = ii; i < i_end; ++i)
                  for (k = kk; k < k_end; ++k)
                    {
                      DATA_TYPE cik = C[i][k];
#pragma omp simd
                      for (j = jj; j < j_end; ++j)
                        F[i][j] += cik * D[k][j];
                    }
              }
          }

      /* G := E*F (tiled) */
#pragma omp for collapse(2) schedule(static)
      for (ii = 0; ii < _PB_NI; ii += TI)
        for (jj = 0; jj < _PB_NL; jj += TJ)
          {
            int i_end = ii + TI; if (i_end > _PB_NI) i_end = _PB_NI;
            int j_end = jj + TJ; if (j_end > _PB_NL) j_end = _PB_NL;

            for (i = ii; i < i_end; ++i)
              for (j = jj; j < j_end; ++j)
                G[i][j] = SCALAR_VAL(0.0);

            for (kk = 0; kk < _PB_NJ; kk += TK)
              {
                int k_end = kk + TK; if (k_end > _PB_NJ) k_end = _PB_NJ;

                for (i = ii; i < i_end; ++i)
                  for (k = kk; k < k_end; ++k)
                    {
                      DATA_TYPE eik = E[i][k];
#pragma omp simd
                      for (j = jj; j < j_end; ++j)
                        G[i][j] += eik * F[k][j];
                    }
              }
          }
    } /* omp parallel */
  }
#pragma endscop

}


