/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  /* Tile the (r,q) space for better cache locality on A and coarser OpenMP granularity.
     Make sum thread-private to avoid races (original sum is reused across q). */
#pragma omp parallel default(none) shared(A,C4) firstprivate(nr,nq,np) private(r,q,p,s,sum)
  {
    const int TR = 8;
    const int TQ = 8;
    int rr, qq;

#pragma omp for schedule(static) collapse(2)
    for (rr = 0; rr < _PB_NR; rr += TR)
      for (qq = 0; qq < _PB_NQ; qq += TQ)
	for (r = rr; r < rr + TR && r < _PB_NR; r++)
	  for (q = qq; q < qq + TQ && q < _PB_NQ; q++)  {

	    for (p = 0; p < _PB_NP; p++) {
	      DATA_TYPE acc = SCALAR_VAL(0.0);
#pragma omp simd reduction(+:acc)
	      for (s = 0; s < _PB_NP; s++)
		acc += A[r][q][s] * C4[s][p];
	      A[r][q][p] = acc;
	    }

	  }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}

