static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
      {
	A[i] = ((DATA_TYPE) i+ 2) / n;
	B[i] = ((DATA_TYPE) i+ 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  /* Spatial blocking over i for improved cache locality and parallel granularity.
     Keep time loop sequential due to true dependences between steps and phases. */
  {
    const int Np = _PB_N;
    const int last = Np - 1;
    const int BS = 256;

#pragma omp parallel default(none) shared(A,B) firstprivate(last) private(t,i)
    for (t = 0; t < _PB_TSTEPS; t++)
      {
#pragma omp for schedule(static)
        for (int ii = 1; ii < last; ii += BS)
          {
            int iend = ii + BS;
            if (iend > last) iend = last;
#pragma omp simd
            for (i = ii; i < iend; i++)
              B[i] = (DATA_TYPE)0.33333 * (A[i-1] + A[i] + A[i + 1]);
          }

#pragma omp for schedule(static)
        for (int ii = 1; ii < last; ii += BS)
          {
            int iend = ii + BS;
            if (iend > last) iend = last;
#pragma omp simd
            for (i = ii; i < iend; i++)
              A[i] = (DATA_TYPE)0.33333 * (B[i-1] + B[i] + B[i + 1]);
          }
      }
  }
#pragma endscop

}


