/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  {
    /* spatial tiling for better cache locality; single persistent team to reduce fork/join */
    const int Ti = 32;
    const int Tj = 64;

    #pragma omp parallel default(none) shared(A,B) private(t,i,j)
    for (t = 0; t < _PB_TSTEPS; t++)
      {
        /* A -> B */
        #pragma omp for schedule(static)
        for (i = 1; i < _PB_N - 1; i += Ti)
          for (j = 1; j < _PB_N - 1; j += Tj)
            {
              int ii, jj;
              int iimax = i + Ti; if (iimax > _PB_N - 1) iimax = _PB_N - 1;
              int jjmax = j + Tj; if (jjmax > _PB_N - 1) jjmax = _PB_N - 1;

              for (ii = i; ii < iimax; ii++)
                {
                  #pragma omp simd
                  for (jj = j; jj < jjmax; jj++)
                    B[ii][jj] = SCALAR_VAL(0.2) * (A[ii][jj] + A[ii][jj-1] + A[ii][1+jj] + A[1+ii][jj] + A[ii-1][jj]);
                }
            }

        #pragma omp barrier

        /* B -> A */
        #pragma omp for schedule(static)
        for (i = 1; i < _PB_N - 1; i += Ti)
          for (j = 1; j < _PB_N - 1; j += Tj)
            {
              int ii, jj;
              int iimax = i + Ti; if (iimax > _PB_N - 1) iimax = _PB_N - 1;
              int jjmax = j + Tj; if (jjmax > _PB_N - 1) jjmax = _PB_N - 1;

              for (ii = i; ii < iimax; ii++)
                {
                  #pragma omp simd
                  for (jj = j; jj < jjmax; jj++)
                    A[ii][jj] = SCALAR_VAL(0.2) * (B[ii][jj] + B[ii][jj-1] + B[ii][1+jj] + B[1+ii][jj] + B[ii-1][jj]);
                }
            }

        #pragma omp barrier
      }
  }
#pragma endscop

}


